function beautifulSubarrays(nums) {
  const seen = new Map();
  seen.set(0, 1);
  let prefix = 0;
  let count = 0;

  for (const num of nums) {
    prefix ^= num;
    const matches = seen.get(prefix) ?? 0;
    count += matches;
    seen.set(prefix, matches + 1);
  }
  return count;
}

