function beautifulSubarrays(nums) {
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    const ones = new Array(21).fill(0);
    for (let end = start; end < nums.length; end++) {
      for (let bit = 0; bit < 21; bit++) if ((nums[end] >> bit) & 1) ones[bit]++;
      if (ones.every(c => c % 2 === 0)) total++;
    }
  }
  return total;
}

