function generate(rand, size) {
  const pick = (limit) => Math.floor(rand() * (limit + 1));
  if (size === 'large') {
    const n = 2000;
    const mode = Math.floor(rand() * 3);
    if (mode === 0) return [Array.from({ length: n }, () => pick(15))];
    if (mode === 1) return [Array.from({ length: n }, () => pick(1000000))];
    const pool = Array.from({ length: 6 }, () => pick(1000000));
    return [Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)])];
  }
  const n = 1 + Math.floor(rand() * 10);
  const limits = [0, 1, 3, 7, 1000000];
  const limit = limits[Math.floor(rand() * limits.length)];
  return [Array.from({ length: n }, () => pick(limit))];
}
